# Specifiche degli approfondimenti animati · Letteratura V · Lezione 4 (solo materiale del docente)
# [[n]] = istante in cui compare l'elemento n (si toglie prima di mandare il testo alla voce)
AN = [
 dict(id='AN01', dopo='D1', kind='cards', label='APPROFONDIMENTO', titolo='Il contesto: Positivismo e Taine',
  screens=[[
   dict(tag='Positivismo', h='Fiducia nella scienza', t='La scienza è lo strumento del progresso.'),
   dict(tag='Hippolyte Taine', h='Tre fattori', t='Ereditarietà biologica · ambiente sociale · momento storico.'),
   dict(tag='Dalla filosofia al romanzo', h='Lo scrittore osserva', t='Racconta la realtà senza giudicare.')]],
  testo="""Facciamo un passo indietro, per capire da dove nasce il Naturalismo. Siamo in Francia, nella seconda metà dell'Ottocento. Il clima culturale è quello del Positivismo. [[1]]Che cosa significa? Significa avere fiducia nella scienza, vista come lo strumento del progresso, capace di migliorare la condizione dell'umanità. Il Positivismo non è una dottrina letteraria, è una dottrina filosofica. Ma piace moltissimo ad alcuni romanzieri francesi. [[2]]Accanto al Positivismo, c'è il filosofo Hippolyte Taine. Secondo Taine, le manifestazioni dello spirito umano sono determinate da tre fattori. Il primo è l'ereditarietà biologica, la cosiddetta razza: quello che hai dentro, i tuoi geni. Il secondo è l'ambiente sociale, il milieu: quello che ti condiziona dall'esterno. Il terzo è il momento storico. Pensa a un genio che nasce in un ambiente arretrato: probabilmente non riuscirà a esprimersi al massimo. Non conta solo quello che sei geneticamente. [[3]]Ecco allora l'idea di fondo. La realtà si può interpretare con le scienze naturali, e l'uomo è un prodotto dell'ereditarietà e dell'ambiente. Questa idea entra nel romanzo. Lo scrittore guarda la società come uno scienziato guarda un campione di studio: senza giudicare, senza commentare. Racconta in modo impersonale, e cerca l'oggettività."""),
 dict(id='AN02', dopo='D1', kind='mappa', titolo='Il Naturalismo francese',
  rami=[dict(concetto='Positivismo',parola='scienza',esempio='fiducia nel progresso'),
        dict(concetto='Taine',parola='tre fattori',esempio='razza, ambiente, momento'),
        dict(concetto='Precursori',parola='realismo',esempio='Balzac e Flaubert'),
        dict(concetto='Il metodo',parola='scientifico',esempio='la realtà come esperimento'),
        dict(concetto='Il narratore',parola='impersonale',esempio='non giudica, non commenta'),
        dict(concetto='Il caposcuola',parola='Zola',esempio='Il romanzo sperimentale')],
  testo="""Mettiamo ordine con una mappa del Naturalismo francese. Al centro, il Naturalismo. [[1]]Il primo ramo è il Positivismo: fiducia nella scienza come strumento di progresso. [[2]]Il secondo è Taine, con i suoi tre fattori: ereditarietà biologica, ambiente sociale e momento storico. [[3]]Il terzo ramo sono i precursori. Honoré de Balzac, nel primo Ottocento, racconta la realtà con un'attitudine scientifica e ne critica le dinamiche. Gustave Flaubert, a metà secolo, porta la teoria dell'impersonalità. Sono realisti, non ancora veri naturalisti. [[4]]Il quarto ramo è il metodo: il metodo scientifico applicato alla narrazione della realtà, come in un esperimento. [[5]]Il quinto è il narratore impersonale: non scrive per distruggere, non scrive per glorificare, non parla di sé. Non giudica e non commenta. [[6]]Infine, il caposcuola: Émile Zola, con il saggio Il romanzo sperimentale. Ricordati queste parole chiave: Positivismo, Taine, impersonalità, esperimento."""),
 dict(id='AN03', dopo='D2', kind='cards', label='APPROFONDIMENTO', titolo='Zola: il romanzo sperimentale',
  screens=[[
   dict(tag='1880', h='Il romanzo sperimentale', t='Lo scrittore è come uno scienziato.'),
   dict(tag='Il metodo', h='Un campione di studio', t='Una città, una classe sociale, un mestiere.'),
   dict(tag='Il ciclo', h='I Rougon-Macquart', t='Venti romanzi su una famiglia.')],
   [dict(tag='1852 – 1870', h='Il Secondo Impero', t='Il regno di Napoleone III.'),
    dict(tag='I temi', h='Alcolismo e miseria', t='La degradazione degli operai parigini.'),
    dict(tag='Due titoli', h="L'Assommoir · Germinal", t='Romanzi industriali e urbani.')]],
  testo="""Ora entriamo nell'opera di Émile Zola. Il vero teorizzatore del movimento. [[1]]Nel saggio Il romanzo sperimentale, del 1880, Zola equipara lo scrittore a uno scienziato. Il romanzo deve funzionare come un esperimento: serve a dimostrare le leggi di Taine, cioè l'influsso dell'ereditarietà e dell'ambiente sui comportamenti umani. [[2]]Lo scrittore sceglie un campione di studio. Può essere una città, una classe sociale, una categoria lavorativa. Lo analizza in modo impersonale, e riferisce il risultato, come uno scienziato che racconta l'esperimento. [[3]]Questa visione si traduce in un ciclo monumentale: i Rougon-Macquart. Sono venti romanzi, che tracciano la storia naturale e sociale di una famiglia. [[4]]Siamo durante il Secondo Impero francese, tra il 1852 e il 1870: l'impero di Napoleone III. [[5]]In questi romanzi trovi i grandi problemi sociali: l'alcolismo, e la degradazione degli operai parigini. [[6]]I titoli più celebri sono L'Assommoir e Germinal. Sono romanzi industriali e urbani, che parlano di operai e di minatori. Ricordati: questo è il modello a cui guarderà Verga."""),
 dict(id='AN04', dopo='D2', kind='mappa', titolo='Émile Zola',
  rami=[dict(concetto='Il caposcuola',parola='Naturalismo',esempio='teorizza il movimento'),
        dict(concetto='Scrittore e scienziato',parola='esperimento',esempio='Il romanzo sperimentale, 1880'),
        dict(concetto='Le leggi di Taine',parola='ereditarietà',esempio='e influsso dell\'ambiente'),
        dict(concetto='Il grande ciclo',parola='Rougon-Macquart',esempio='venti romanzi'),
        dict(concetto='I temi',parola='miseria',esempio='alcolismo, operai parigini'),
        dict(concetto='Gli ultimi anni',parola='messianismo',esempio='Tre città, Quattro vangeli')],
  testo="""Riassumiamo Zola con una mappa. Al centro, Émile Zola. [[1]]Primo ramo: il caposcuola. Zola teorizza il Naturalismo e gli dà il suo volto più scientifico, più obiettivo e più sociale. [[2]]Secondo ramo: lo scrittore e lo scienziato. Nel saggio Il romanzo sperimentale, del 1880, il romanzo diventa un esperimento. [[3]]Terzo ramo: le leggi di Taine. Il romanzo dimostra l'ereditarietà e l'influsso dell'ambiente sui comportamenti umani. [[4]]Quarto ramo: il grande ciclo dei Rougon-Macquart. Venti romanzi sulla storia di una famiglia, durante il Secondo Impero. [[5]]Quinto ramo: i temi. L'alcolismo, la miseria, la degradazione degli operai parigini, in romanzi come L'Assommoir e Germinal. [[6]]Sesto ramo: gli ultimi anni. Zola si allontana dai canoni naturalisti, con il ciclo delle Tre città e quello, incompiuto, dei Quattro vangeli, e si orienta verso un messianismo umanitario. Ricordati: se all'esame ti chiedono Verga, ti chiedono anche Zola."""),
 dict(id='AN05', dopo='D3', kind='mix', label='APPROFONDIMENTO', titolo='Dalla Francia all\'Italia',
  screens=[[
   dict(tag='Anni Settanta', h='Zola a Milano', t='Lo accolgono gli ambienti di sinistra.'),
   dict(tag='Il limite', h='Nessuna teoria', t='Solo denunce e effetti scandalistici.'),
   dict(tag='La svolta', h='Il Sud conservatore', t='Luigi Capuana e Giovanni Verga.')],
   [dict(kind='righe', tag='Ambiente', a='Francia: città e industria', b='Italia: campagna e mondo rurale'),
    dict(kind='righe', tag='Protagonisti', a='Operai e sottoproletariato', b='Contadini e ceti umili'),
    dict(kind='righe', tag='Scienza', a='Lo scrittore è uno scienziato', b='Conta solo la tecnica impersonale')]],
  testo="""Vediamo come il modello di Zola arriva in Italia. [[1]]Negli anni Settanta, l'Italia è appena unita e sta cercando di costruirsi anche come paese industriale. Il modello di Zola trova terreno fertile negli ambienti culturali milanesi di sinistra. Sono repubblicani e socialisti: guardano con interesse alle questioni sociali, che danno fastidio alla borghesia e alla classe dirigente monarchica. Milano, poi, è la città più avanzata dal punto di vista editoriale. [[2]]Ma la sinistra milanese non riesce a elaborare una teoria artistica organica. Guarda alla Francia, e si limita a denunce frammentarie, oppure a cercare effetti scandalistici legati alla vita degli emarginati. [[3]]La vera svolta si deve a due intellettuali meridionali e conservatori: Luigi Capuana e Giovanni Verga. Ora confrontiamo i due modelli. [[4]]Zola racconta la città e l'industria. In Italia l'industria è più debole, e Verga, siciliano, racconta una realtà agricola e rurale. [[5]]Quindi, in Francia i protagonisti sono operai e sottoproletariato urbano, in Italia sono i contadini. [[6]]E la scienza? Per Zola lo scrittore è uno scienziato che fa un esperimento. Per Capuana e Verga la scientificità sta soltanto nella tecnica di rappresentazione: l'impersonalità. Il metodo è lo stesso, ma l'uso è diverso."""),
 dict(id='AN06', dopo='D3', kind='timeline', label='APPROFONDIMENTO', titolo='Capuana, Serao, Aleramo: le opere',
  screens=[[
   dict(tag='1879', h='Giacinta', t='Capuana: un caso psicopatologico.'),
   dict(tag='1884', h='Il ventre di Napoli', t='Serao: la realtà popolare napoletana.'),
   dict(tag='1885', h="Per l'arte", t="Capuana: l'arte è autonoma dalla scienza.")],
   [dict(tag='1887', h='Riccardo Joanna', t='Serao, dopo La conquista di Roma.'),
    dict(tag='1901', h='Il marchese di Roccaverdina', t='Capuana: romanzo tardo.'),
    dict(tag='1906', h='Una donna', t='Sibilla Aleramo: la condizione femminile.')]],
  testo="""Mettiamo in fila le opere degli autori che abbiamo incontrato, seguendo gli anni. [[1]]Nel 1879 Luigi Capuana pubblica Giacinta, un romanzo influenzato dal Naturalismo di Zola e incentrato su un caso di psicopatologia. [[2]]Nel 1884 esce Il ventre di Napoli, di Matilde Serao. Riprende il modello del ventre di Parigi, ed è un'inchiesta giornalistica sulla realtà napoletana. [[3]]Nel 1885 Capuana pubblica il volume Per l'arte, in cui rivendica l'autonomia dell'arte dalla scienza. Finirà per subire le suggestioni del nuovo clima spiritualista e antipositivista di fine secolo. Nello stesso anno, Matilde Serao scrive La conquista di Roma, un romanzo di critica sociale e parlamentare. [[4]]Nel 1887 arriva Vita e avventure di Riccardo Joanna: la Serao sta abbandonando i moduli veristi, verso l'analisi psicologica delle passioni amorose e poi verso tendenze mistiche. [[5]]Nel 1901, Capuana scrive Il marchese di Roccaverdina, il suo romanzo più tardo. [[6]]E nel 1906 esce Una donna, di Sibilla Aleramo, pseudonimo di Rina Faccio. Affonda le radici nel clima naturalista, per il coraggio con cui affronta gravi problemi sociali: la condizione femminile, e l'oppressione familiare."""),
 dict(id='AN07', dopo='D3', kind='mappa', titolo='Il Verismo italiano',
  rami=[dict(concetto='Il contesto',parola='Milano',esempio='anni Settanta, sinistra'),
        dict(concetto='Capuana e Verga',parola='svolta',esempio='intellettuali meridionali'),
        dict(concetto="L'impersonalità",parola='eclisse',esempio='scompare chi giudica'),
        dict(concetto="L'arte è autonoma",parola='libertà',esempio='né scienza né politica'),
        dict(concetto='Un\'etichetta',parola='generica',esempio='nessuna scuola organizzata'),
        dict(concetto='I temi',parola='ceti umili',esempio='colore locale, regioni')],
  testo="""Costruiamo la mappa del Verismo italiano. Al centro, il Verismo. [[1]]Il primo ramo è il contesto: gli anni Settanta, gli ambienti milanesi di sinistra che fanno conoscere Zola. [[2]]Il secondo è la svolta: la elaborano due intellettuali meridionali e conservatori, Luigi Capuana e Giovanni Verga. [[3]]Terzo ramo: l'impersonalità. È l'eclisse dell'autore, la scomparsa del narratore tradizionale che giudica e commenta. Non porta il lettore per mano, come faceva Manzoni: descrive in modo nudo e crudo. [[4]]Quarto ramo: l'autonomia dell'arte. Capuana e Verga rifiutano di subordinare la letteratura alla scienza, alla politica o a scopi sociali. [[5]]Quinto ramo: un'etichetta generica. A differenza del Naturalismo francese, il Verismo non è una scuola organizzata, con un programma comune. [[6]]Sesto ramo: i temi. Le miserie delle classi più umili, il colore locale, le realtà regionali. Ricordati: gli scrittori veristi condividono solo un generico riferimento alla realtà."""),
 dict(id='AN08', dopo='D4', kind='mix', label='APPROFONDIMENTO', titolo='Flaubert e Madame Bovary',
  screens=[[
   dict(tag='1857', h='Madame Bovary', t='Emma, moglie di un medico di provincia.'),
   dict(tag='Il bovarismo', h='Evadere dalla noia', t='Sogna le vite dei romanzi romantici.'),
   dict(tag='La fine', h='Un romanzo crudo', t="Il suicidio di Emma fece scalpore.")],
   [dict(kind='righe', tag='Diretto', a='Emma disse: «Non mi interessa».', b=''),
    dict(kind='righe', tag='Indiretto', a='Emma disse che non le interessava.', b=''),
    dict(kind='righe', tag='Indiretto libero', a='Non le interessava affatto.', b='', ev=True)]],
  testo="""Torniamo a Gustave Flaubert, per guardare da vicino il suo romanzo più famoso. [[1]]Madame Bovary esce nel 1857. La protagonista è Emma Bovary, moglie di un medico di provincia. Il romanzo è incentrato sulla sua brama di evasione dalla realtà e sulla sua frustrazione esistenziale. [[2]]Emma legge romanzi che mostrano vite meravigliose, e vorrebbe viverle. Ma la sua vita è noiosissima. Questo atteggiamento, nato dalle letture romantiche, si chiama bovarismo. [[3]]La storia si chiude in modo molto crudo: Emma sceglie di togliersi la vita. Il romanzo fece molto scalpore, all'epoca. Dal punto di vista della tecnica, Flaubert introduce l'impersonalità: il narratore non esprime giudizi, si eclissa, e adotta la focalizzazione interna. La realtà passa attraverso la coscienza dei personaggi. Questa ricerca porta al discorso indiretto libero. Guardiamolo con un esempio molto semplice. [[4]]Nel discorso diretto, il personaggio parla tra virgolette, dopo i due punti. [[5]]Nel discorso indiretto, c'è un verbo di dichiarazione: disse che. [[6]]Nel discorso indiretto libero, il verbo di dichiarazione scompare. Si riportano i pensieri e il modo di esprimersi del personaggio, e la voce del narratore si fonde con la sua. È una tecnica che userà anche Verga."""),
 dict(id='AN09', dopo='D4', kind='mappa', titolo='Flaubert e Madame Bovary',
  rami=[dict(concetto='Il precursore',parola='realismo',esempio='dopo Balzac, a metà Ottocento'),
        dict(concetto='Madame Bovary',parola='1857',esempio='Emma, medico di provincia'),
        dict(concetto='Il bovarismo',parola='evasione',esempio='noia e letture romantiche'),
        dict(concetto="L'impersonalità",parola='eclisse',esempio='il narratore non giudica'),
        dict(concetto='La tecnica',parola='indiretto libero',esempio='focalizzazione interna'),
        dict(concetto='Verso il Verismo',parola='ceti popolari',esempio='dalla borghesia ai contadini')],
  testo="""Chiudiamo con la mappa di Flaubert. Al centro, Flaubert e Madame Bovary. [[1]]Primo ramo: il precursore. Flaubert viene dopo Balzac e apre la strada al Naturalismo, ma resta un realista. [[2]]Secondo ramo: Madame Bovary, del 1857, la storia di Emma, moglie di un medico di provincia. [[3]]Terzo ramo: il bovarismo, la brama di evasione dalla noia, alimentata dalle letture romantiche. [[4]]Quarto ramo: l'impersonalità. Il narratore si eclissa e non esprime giudizi. [[5]]Quinto ramo: la tecnica. La focalizzazione interna, e il discorso indiretto libero, che fonde la voce del narratore con quella del personaggio. [[6]]Sesto ramo: verso il Verismo. Flaubert racconta la borghesia, e la sua frustrazione. I veristi spostano l'interesse sulle classi popolari, e raccontano coloro che soffrono e che lavorano duramente. Nella prossima lezione parleremo proprio di Giovanni Verga."""),
 dict(id='AN10', dopo='Q4', kind='mappa', titolo='Naturalismo e Verismo', finale=True,
  rami=[dict(concetto='Il Naturalismo',parola='Francia',esempio='metodo scientifico'),
        dict(concetto='I precursori',parola='Balzac, Flaubert',esempio='Madame Bovary, 1857'),
        dict(concetto='Émile Zola',parola='caposcuola',esempio='Rougon-Macquart'),
        dict(concetto='Il Verismo',parola='Italia',esempio='anni Settanta, Milano'),
        dict(concetto='Capuana e Verga',parola='impersonalità',esempio="l'eclisse dell'autore"),
        dict(concetto='Serao e Aleramo',parola='eredi',esempio='Una donna, 1906')],
  testo="""Ed ecco la mappa di tutta la lezione. Al centro, Naturalismo e Verismo. [[1]]A sinistra, il Naturalismo francese: nasce nella seconda metà dell'Ottocento, sotto l'influenza del Positivismo, e applica il metodo scientifico alla narrazione della realtà. [[2]]I precursori sono Balzac e Flaubert, due realisti. Flaubert scrive Madame Bovary, nel 1857, e introduce l'impersonalità e il discorso indiretto libero. [[3]]Il caposcuola è Émile Zola, con il saggio Il romanzo sperimentale e il ciclo dei Rougon-Macquart. [[4]]Poi il Verismo italiano. Arriva negli anni Settanta, grazie agli ambienti milanesi di sinistra, ed è un'etichetta generica, non una scuola. [[5]]Le due figure chiave sono Luigi Capuana e Giovanni Verga, che riprendono dal Naturalismo soprattutto l'impersonalità, l'eclisse dell'autore. [[6]]Infine, le autrici che mostrano l'evoluzione del movimento: Matilde Serao, con Il ventre di Napoli, e Sibilla Aleramo, con Una donna, del 1906. Rivedi la mappa con calma, e poi passa al glossario."""),
]

_nuovi = {
 'prec': dict(dopo='D1', kind='cards', label='APPROFONDIMENTO', titolo='I precursori: Balzac e Flaubert',
  screens=[[
   dict(tag='Primo Ottocento', h='Honoré de Balzac', t='Racconta la realtà con attitudine scientifica.'),
   dict(tag='Metà secolo', h='Gustave Flaubert', t="La teoria dell'impersonalità."),
   dict(tag='Realisti', h='Non ancora naturalisti', t='Preparano le radici del movimento.')]],
  testo="""Il Naturalismo non nasce dal nulla. Ha dei precursori, e sono due grandi romanzieri francesi. [[1]]Il primo è Honoré de Balzac, nel primo Ottocento. Balzac racconta la realtà vera del suo tempo. Lo fa con un'attitudine scientifica nell'analizzare la società, e con l'intenzione di criticarla. Prende in giro le classi sociali, e si prende gioco di certe dinamiche: il ricco, per esempio, diventa ridicolo. [[2]]Il secondo è Gustave Flaubert, a metà del secolo. Con lui compare la teoria dell'impersonalità. Racconta la realtà, prima di tutto, e usa una tecnica narrativa impersonale: non ti fa sentire il suo giudizio, te la racconta, e tu guardi. Certo, in questo racconto lancia comunque dei messaggi. [[3]]Vedi che gli elementi ci sono già tutti: la realtà come tema, e l'impersonalità come tecnica. Però Balzac e Flaubert sono, in senso stretto, dei realisti. Il vero movimento naturalista arriva nel secondo Ottocento, con Émile Zola, che prende la tecnica di Flaubert ma parla di cose più politiche e sociali, in modo più incisivo."""),
 'gonc': dict(dopo='D2', kind='cards', label='APPROFONDIMENTO', titolo='Intorno a Zola',
  screens=[[
   dict(tag='Edmond e Jules', h='I fratelli Goncourt', t='Documentazione minuta e precisa, da cronisti.'),
   dict(tag='Il loro metodo', h='Dalla cronaca al romanzo', t='Storie vere, con i nomi cambiati.'),
   dict(tag='Dentro Zola', h='Pietà e sdegno', t='Sotto il rigore materialista, un cuore romantico.')]],
  testo="""Accanto a Zola operano altri scrittori che seguono la stessa strada. [[1]]Sono i fratelli Edmond e Jules de Goncourt. Sono noti per l'attenzione alla documentazione minuta e precisa, come dei giornalisti che fanno cronaca dettagliata. [[2]]Solo che si dedicano alla letteratura. Spesso partono dalla cronaca, cambiano i nomi dei personaggi, e le storie vere diventano romanzi. La fantasia è ridotta a vantaggio dell'obiettività, e del messaggio sociale e politico che resta sullo sfondo. È un tipo di narrazione molto diverso da quello romantico. [[3]]Anche in Zola c'è qualcosa di più. Nonostante il rigore materialista della sua poetica, convivono tendenze romantiche e decadenti. Si vedono nella trasformazione lirica di oggetti e ambienti, e in una forte carica di pietà e di sdegno sociale. Per questo i suoi romanzi sono crudi, ma non sono freddi: vogliono smuovere le coscienze."""),
 'capu': dict(dopo='D3', kind='cards', label='APPROFONDIMENTO', titolo='La poetica di Capuana',
  screens=[[
   dict(tag='Il critico', h='Corriere della Sera', t='Sostiene con vigore l\'opera di Zola.'),
   dict(tag='Il rifiuto', h='Nessuna subordinazione', t='Né alla scienza, né alla politica.'),
   dict(tag='La scientificità', h='Solo nella tecnica', t="L'impersonalità dell'opera d'arte.")]],
  testo="""Fermiamoci sulla poetica di Luigi Capuana. [[1]]Prima di tutto, Capuana è un critico letterario. Scrive sul Corriere della Sera, e sostiene con vigore l'opera di Zola. [[2]]Però rifiuta una cosa: la subordinazione della letteratura alla scienza e alla politica. Obiettivo, sì. Ma lo scrittore non è uno scienziato, e non deve occuparsi soltanto di questioni politiche e sociali. Scrive in modo impersonale, ma scrive quello che vuole: non ha un manifesto programmatico da seguire. [[3]]Per Capuana, e poi per Verga, la scientificità non consiste nel dimostrare tesi scientifiche in un romanzo. Si risolve esclusivamente nella tecnica espressiva, incentrata sul principio dell'impersonalità. L'autore sta fuori dall'opera: non ti dice che cosa pensare, non porta per mano il lettore. Descrive, e lascia al lettore la sentenza. È l'eclisse dell'autore, e la scomparsa del narratore onnisciente tradizionale."""),
}
_ordine = ['AN01','prec','AN02','AN03','gonc','AN04','AN05','capu','AN06','AN07','AN08','AN09','AN10']
_vecchi = {a['id']: a for a in AN}
AN = []
for k in _ordine:
    AN.append(_vecchi[k] if k in _vecchi else _nuovi[k])
# riordino: D1 [AN01,prec,AN02]; D2 [AN03,gonc,AN04]; D3 [AN05,capu,AN06,AN07]; D4 [AN08,AN09]; Q4 [AN10]
for i, a in enumerate(AN, 1):
    a['id'] = 'AN%02d' % i
